#!/usr/bin/env python3
import argparse
import re
import sys
from pathlib import Path

IMPORT = re.compile(r"^using[ \t]*\{([^}]*)\}[ \t]*$")
IMPORT_START = re.compile(r"^using\b")
MODULE = re.compile(r"^[A-Za-z_]\w*[ \t]*(?:<[^>\n]*>[ \t]*)*:=[ \t]*module[ \t]*:[ \t]*$")
SCOPED = re.compile(r"<[ \t]*scoped[ \t]*\{[^}]*\}[ \t]*>")
ACCESS = re.compile(r"<[ \t]*(?:public|scoped[ \t]*\{[^}]*\})[ \t]*>")
DOUBLE = re.compile(r"(<(?:public|internal)>)(?:[ \t]*\1)+")
STRUCT = re.compile(r"^([ \t]*)[A-Za-z_]\w*[ \t]*(?:<[^>\n]*>[ \t]*)*(?:\([^)\n]*\))?[ \t]*(?:<[^>\n]*>[ \t]*)*:=[ \t]*struct\b[^\n#]*:[ \t]*(?:#.*)?$")
STRUCT_START = re.compile(r":=[ \t]*struct\b")

class BundleError(Exception):
    pass

def read(path):
    return path.read_text(encoding="utf-8-sig").replace("\r\n", "\n").replace("\r", "\n")

def restrict(text, name):
    result = []
    struct_indent = None
    for number, line in enumerate(text.split("\n"), 1):
        indent = len(line) - len(line.lstrip(" \t"))
        if struct_indent is not None:
            if not line.strip() or line.lstrip().startswith("#") or indent > struct_indent:
                result.append(DOUBLE.sub(r"\1", SCOPED.sub("<public>", line)))
                continue
            struct_indent = None
        match = STRUCT.match(line)
        if match:
            struct_indent = len(match.group(1))
        elif STRUCT_START.search(line):
            raise BundleError(f"{name}:{number}: a struct that cannot be read: {line!r}")
        result.append(DOUBLE.sub(r"\1", ACCESS.sub("<internal>", line)))
    return "\n".join(result)

def process(text, name, imports):
    lines = text.split("\n")
    kept = []
    for number, line in enumerate(lines, 1):
        match = IMPORT.match(line)
        if match:
            for item in match.group(1).split(","):
                item = item.strip()
                if item.startswith("/"):
                    imports.add(item)
            continue
        if IMPORT_START.match(line):
            raise BundleError(f"{name}:{number}: an import was not understood: {line!r}")
        if MODULE.match(line):
            following = next((other for other in lines[number:] if other.strip()), "")
            if following[:1] in (" ", "\t"):
                raise BundleError(f"{name}:{number}: this module has a body, so it cannot be flattened: {line!r}")
            continue
        kept.append(line)
    return restrict("\n".join(kept), name).strip("\n")

def main():
    parser = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    parser.add_argument("roots", nargs="+", type=Path)
    parser.add_argument("--out", required=True, type=Path)
    parser.add_argument("--reference", default="reference.verse")
    parser.add_argument("--tag", default="")
    args = parser.parse_args()

    found = []
    for root in args.roots:
        if not root.is_dir():
            raise BundleError(f"{root} is not a folder")
        found += [(root, path) for path in sorted(root.rglob("*.verse"), key=lambda p: p.relative_to(root).as_posix().lower())]
    if not found:
        raise BundleError("no .verse files found")

    references = [item for item in found if item[1].name.lower() == args.reference.lower()]
    if len(references) != 1:
        raise BundleError(f"expected exactly one {args.reference}, found {len(references)}: {[str(p) for _, p in references]}")
    ordered = references + [item for item in found if item not in references]

    imports, sections = set(), []
    for root, path in ordered:
        name = (root.name + "/" + path.relative_to(root).as_posix())
        body = process(read(path), name, imports)
        if body.strip():
            sections.append(f"# --- {name}\n{body}")

    header = "# VerseBoy" + (f" v{args.tag}" if args.tag else "") + " (standalone). Generated by bundle.py."
    output = header + "\n" + "".join(f"using {{ {item} }}\n" for item in sorted(imports)) + "\n" + "\n\n".join(sections) + "\n"

    leftovers = [n for n, line in enumerate(output.split("\n"), 1) if SCOPED.search(line) or re.match(r"using\s*\{\s*[^/\s]", line)]
    if leftovers:
        raise BundleError(f"the result still has scoped specifiers or local imports on lines {leftovers[:5]}")

    args.out.parent.mkdir(parents=True, exist_ok=True)
    args.out.write_text(output, encoding="utf-8", newline="\n")

if __name__ == "__main__":
    try:
        main()
    except BundleError as error:
        sys.exit(f"error: {error}")